import{_ as d,a as e,c as a,ac as o}from"./chunks/framework.BSuaGltH.js";const p=JSON.parse('{"title":"Linux 常用命令：用途、参数与操作边界 · 维护与旧设备场景","description":"把基础解释与按使用流程排列的命令表集中为一个速查入口。","frontmatter":{"title":"Linux 常用命令：用途、参数与操作边界 · 维护与旧设备场景","description":"把基础解释与按使用流程排列的命令表集中为一个速查入口。","splitFrom":"systems/linux/common-commands.md","showdocs":{"topics":[{"id":"linux","title":"Linux","link":"/topics/linux/"},{"id":"network","title":"网络配置与诊断","link":"/topics/network/"}],"kind":"命令与系统观察","scope":"general","audience":"general","group":"容器与运维","seriesTitle":"Linux 常用命令：用途、参数与操作边界","summary":"把基础解释与按使用流程排列的命令表集中为一个速查入口。","status":"active","related":[{"title":"Linux 常用命令：用途、参数与操作边界","link":"/systems/linux/common-commands","kind":"命令与系统观察","scope":"general","audience":"general"},{"title":"Linux 常用命令：用途、参数与操作边界 · 按发行版选择包管理器至备份与同步","link":"/systems/linux/common-commands-part-06","kind":"命令与系统观察","scope":"general","audience":"general"},{"title":"Linux 常用命令：用途、参数与操作边界 · 浏览、创建与移动文件至文本筛选、统计与比较","link":"/systems/linux/common-commands-part-04","kind":"命令与系统观察","scope":"general","audience":"general"},{"title":"Linux 常用命令：用途、参数与操作边界 · 账号、权限与属性至磁盘容量与挂载","link":"/systems/linux/common-commands-part-05","kind":"命令与系统观察","scope":"general","audience":"general"},{"title":"Linux 常用命令：用途、参数与操作边界 · Linux 基础命令","link":"/systems/linux/common-commands-part-01","kind":"命令与系统观察","scope":"general","audience":"general"}],"prev":{"text":"Linux 常用命令：用途、参数与操作边界 · 按发行版选择包管理器至备份与同步","link":"/systems/linux/common-commands-part-06"},"next":{"text":"Linux awk 基础命令","link":"/systems/linux/plus/ecosystem/linux_awk"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"Linux 常用命令：用途、参数与操作边界 · 按发行版选择包管理器至备份与同步","link":"/systems/linux/common-commands-part-06"},"next":{"text":"Linux awk 基础命令","link":"/systems/linux/plus/ecosystem/linux_awk"}},"headers":[],"relativePath":"systems/linux/common-commands-part-07.md","filePath":"systems/linux/common-commands-part-07.md"}'),r={name:"systems/linux/common-commands-part-07.md"};function c(s,t,n,i,l,m){return e(),a("div",null,[...t[0]||(t[0]=[o('<h1 id="linux-常用命令-用途、参数与操作边界-·-维护与旧设备场景" tabindex="-1">Linux 常用命令：用途、参数与操作边界 · 维护与旧设备场景 <a class="header-anchor" href="#linux-常用命令-用途、参数与操作边界-·-维护与旧设备场景" aria-label="Permalink to &quot;Linux 常用命令：用途、参数与操作边界 · 维护与旧设备场景&quot;">​</a></h1><p><a href="/systems/linux/common-commands">返回分篇目录</a></p><p>先按任务进入主速查；需要理解参数时再展开后面的逐条解释。命令未执行，平台与权限按相应条目核对。</p><h2 id="part-2-维护与旧设备场景" tabindex="-1">维护与旧设备场景 <a class="header-anchor" href="#part-2-维护与旧设备场景" aria-label="Permalink to &quot;维护与旧设备场景 {#part-2-维护与旧设备场景}&quot;">​</a></h2><h3 id="part-2-时钟、重启、关机与会话退出" tabindex="-1">时钟、重启、关机与会话退出 <a class="header-anchor" href="#part-2-时钟、重启、关机与会话退出" aria-label="Permalink to &quot;时钟、重启、关机与会话退出 {#part-2-时钟、重启、关机与会话退出}&quot;">​</a></h3><p><code>clock -w</code> 是来源中向硬件时钟写入系统时间的维护操作，先核对实际工具和时间策略。</p><table tabindex="0"><thead><tr><th>命令</th><th>用途与边界</th></tr></thead><tbody><tr><td><code>shutdown -h now</code></td><td>关闭系统</td></tr><tr><td><code>init 0</code></td><td>关闭系统</td></tr><tr><td><code>telinit 0</code></td><td>关闭系统</td></tr><tr><td><code>shutdown -h hours:minutes &amp;</code></td><td>按预定时间关闭系统</td></tr><tr><td><code>shutdown -c</code></td><td>取消按预定时间关闭系统</td></tr><tr><td><code>shutdown -r now</code></td><td>重启</td></tr><tr><td><code>reboot</code></td><td>重启</td></tr><tr><td><code>logout</code></td><td>注销</td></tr></tbody></table><h3 id="part-2-文件系统检查" tabindex="-1">文件系统检查 <a class="header-anchor" href="#part-2-文件系统检查" aria-label="Permalink to &quot;文件系统检查 {#part-2-文件系统检查}&quot;">​</a></h3><table tabindex="0"><thead><tr><th>命令</th><th>用途与边界</th></tr></thead><tbody><tr><td><code>badblocks -v /dev/hda1</code></td><td>检查磁盘hda1上的坏磁块</td></tr><tr><td><code>fsck /dev/hda1</code></td><td>修复/检查hda1磁盘上linux文件系统的完整性</td></tr><tr><td><code>fsck.ext2 /dev/hda1</code></td><td>修复/检查hda1磁盘上ext2文件系统的完整性</td></tr><tr><td><code>e2fsck /dev/hda1</code></td><td>检查 ext2/ext3/ext4 文件系统；先确认设备未挂载</td></tr><tr><td><code>fsck.ext3 /dev/hda1</code></td><td>修复/检查hda1磁盘上ext3文件系统的完整性</td></tr><tr><td><code>fsck.vfat /dev/hda1</code></td><td>修复/检查hda1磁盘上fat文件系统的完整性</td></tr><tr><td><code>fsck.msdos /dev/hda1</code></td><td>修复/检查hda1磁盘上dos文件系统的完整性</td></tr><tr><td><code>dosfsck /dev/hda1</code></td><td>修复/检查hda1磁盘上dos文件系统的完整性</td></tr></tbody></table><p>检查/修复前确认设备、文件系统类型、挂载状态和已有备份。原 <code>e2fsck -j /dev/hda1</code> 缺少外部日志设备参数，已并入普通检查例；<code>-j</code> 的含义见 <a href="https://manpages.debian.org/bookworm/e2fsprogs/e2fsck.8.en.html" target="_blank" rel="noopener noreferrer">e2fsck 手册</a>。</p><h3 id="part-2-初始化文件系统" tabindex="-1">初始化文件系统 <a class="header-anchor" href="#part-2-初始化文件系统" aria-label="Permalink to &quot;初始化文件系统 {#part-2-初始化文件系统}&quot;">​</a></h3><table tabindex="0"><thead><tr><th>命令</th><th>用途与边界</th></tr></thead><tbody><tr><td><code>mkfs /dev/hda1</code></td><td>在hda1分区创建一个文件系统</td></tr><tr><td><code>mke2fs /dev/hda1</code></td><td>在hda1分区创建一个linux ext2的文件系统</td></tr><tr><td><code>mke2fs -j /dev/hda1</code></td><td>在hda1分区创建一个linux ext3(日志型)的文件系统</td></tr><tr><td><code>mkfs.fat -F 32 /dev/hda1</code></td><td>创建 FAT32 文件系统，写入前必须核对设备</td></tr><tr><td><code>fdformat -n /dev/fd0</code></td><td>格式化一个软盘</td></tr><tr><td><code>mkswap /dev/hda3</code></td><td>创建一个swap文件系统</td></tr></tbody></table><p>这里的 mkfs、mke2fs、mkswap 会写入设备元数据，不能作为“查看磁盘”的命令运行。FAT32 参数结构见 <a href="https://manpages.debian.org/bookworm/dosfstools/mkfs.fat.8.en.html" target="_blank" rel="noopener noreferrer">mkfs.fat 手册</a>。</p><h3 id="part-2-启用-swap" tabindex="-1">启用 Swap <a class="header-anchor" href="#part-2-启用-swap" aria-label="Permalink to &quot;启用 Swap {#part-2-启用-swap}&quot;">​</a></h3><table tabindex="0"><thead><tr><th>命令</th><th>用途与边界</th></tr></thead><tbody><tr><td><code>swapon /dev/hda3</code></td><td>启用一个新的swap文件系统</td></tr><tr><td><code>swapon /dev/hda2</code>；<code>swapon /dev/hdb3</code></td><td>分别启用两个 Swap 分区</td></tr></tbody></table><p>mkswap 的初始化示例统一在上一节保留，swapon 只负责启用。</p><h3 id="part-2-光盘与软盘历史操作" tabindex="-1">光盘与软盘历史操作 <a class="header-anchor" href="#part-2-光盘与软盘历史操作" aria-label="Permalink to &quot;光盘与软盘历史操作 {#part-2-光盘与软盘历史操作}&quot;">​</a></h3><details><summary>展开光盘制作、刻录与音轨案例</summary><table tabindex="0"><thead><tr><th>命令</th><th>用途与边界</th></tr></thead><tbody><tr><td><code>cdrecord -v gracetime=2 dev=/dev/cdrom -eject blank=fast -force</code></td><td>清空一个可复写的光盘内容</td></tr><tr><td><code>mkisofs -J -allow-leading-dots -R -V &quot;Label CD&quot; -iso-level 4 -o ./cd.iso data_cd</code></td><td>创建一个目录的iso镜像文件</td></tr><tr><td><code>cdrecord -v dev=/dev/cdrom cd.iso</code></td><td>刻录一个ISO镜像文件</td></tr><tr><td><code>gzip -dc cd_iso.gz | cdrecord dev=/dev/cdrom -</code></td><td>刻录一个压缩了的ISO镜像文件</td></tr><tr><td><code>mount -o loop cd.iso /mnt/iso</code></td><td>挂载一个ISO镜像文件</td></tr><tr><td><code>cd-paranoia -B</code></td><td>从一个CD光盘转录音轨到 wav 文件中</td></tr><tr><td><code>cd-paranoia -- &quot;-3&quot;</code></td><td>从一个CD光盘转录音轨到 wav 文件中（参数-3）</td></tr><tr><td><code>cdrecord --scanbus</code></td><td>扫描总线以识别scsi通道</td></tr><tr><td><code>dd if=/dev/hdc | md5sum</code></td><td>校验一个设备的md5sum编码，例如一张 CD</td></tr></tbody></table><p>这里保留目录制作 ISO、刻录、挂载和音轨场景；光盘整盘镜像归入上文块设备备份，不把 <code>/dev/cdrom</code> 当成 mkisofs 的目录输入。这些命令依赖实际设备、权限及相应工具；不要把旧 /dev/hd* 或软盘设备名直接套到当前机器。</p></details>',18)])])}const u=d(r,[["render",c]]);export{p as __pageData,u as default};
